function waysToReachStair(k) {
  const comb = [];
  for (let n = 0; n <= 32; n++) {
    comb.push(new Array(n + 1).fill(1));
    for (let r = 1; r < n; r++) {
      comb[n][r] = comb[n - 1][r - 1] + comb[n - 1][r];
    }
  }
  let ways = 0;
  for (let ups = 0; ups <= 31; ups++) {
    const downs = 2 ** ups - k;
    if (downs > ups + 1) {
      break;
    }
    if (downs >= 0) {
      ways += comb[ups + 1][downs];
    }
  }
  return ways;
}

