function waysToReachStair(k) {
  // Count move sequences directly: state is (stair, jump, whether a down move is allowed now).
  const memo = new Map();
  const count = (stair, jump, canDown) => {
    if (stair > k + 1) return 0;
    const key = stair + ',' + jump + ',' + canDown;
    if (memo.has(key)) return memo.get(key);
    let total = stair === k ? 1 : 0;
    if (canDown && stair > 0) total += count(stair - 1, jump, false);
    total += count(stair + 2 ** jump, jump + 1, true);
    memo.set(key, total);
    return total;
  };
  return count(1, 0, true);
}

