function generate(rand, size) {
  const pick = rand();
  if (size === 'small' && pick < 0.5) return [Math.floor(rand() * 40)];
  if (pick < 0.85) {
    // A stair just below a power of two, so the answer is usually not zero.
    const ups = Math.floor(rand() * (size === 'large' ? 30 : 12));
    const downs = Math.floor(rand() * (ups + 3));
    return [Math.max(0, 2 ** ups - downs)];
  }
  return [Math.floor(rand() * (size === 'large' ? 1e9 + 1 : 5000))];
}
